    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  function comparison() {
    const left = sum();
    if (!comparisonOperators.has(current().value)) return left;
    const operands = [left];
    const operators = [];
    do {
      operators.push(take());
      operands.push(sum());
    } while (comparisonOperators.has(current().value));
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (['*', '/', '//', '%'].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  function unary() {
    if (is('+') || is('-')) {
      return { type: 'unary', operator: take(), operand: unary() };
    }
    return power();
  }

  function power() {
    const left = primary();
    if (!is('**')) return left;
    const operator = take();
    return binary(operator, left, unary());
  }

