'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { evaluate, ExprError } = require('./src');

function errorAt(source, column, variables) {
  assert.throws(() => evaluate(source, variables), error =>
    error instanceof ExprError && error.name === 'ExprError' && error.column === column,
    source);
}

test('arithmetic grammar, literals, calls, and boolean coercion', () => {
  const cases = [
    ['-2 ** 2', -4], ['(-2) ** 2', 4], ['2 ** -1', 0.5],
    ['2 ** 3 ** 2', 512], ['-2 ** -2', -0.25], ['2 ** -2 ** 2', 0.0625],
    ['--2 ** 2', 4], ['2 * -3 ** 2', -18], ['8 / 2 * 3', 12],
    ['10 - 3 - 2', 5], ['1 + 2 * 3 ** 2', 19],
    ['.5 + 5. + 1.5e-3 + 2E+1', 25.5015],
    ['min(3, max(2, 5), abs(-4))', 3], ['max(3)', 3],
    ['3 > 2 > 1', true], ['1 < 2 <= 2 == 2 != 3 > 0', true],
    ['(1 < 2) + (2 < 1)', 1], ['(1 < 2) == 1', true],
    ['(2 < 1) == 0', true], ['(1 < 2) ** 2', 1],
    ['abs(2 < 1)', 0], ['min(1 < 2, 3)', 1],
    ['_x + x2', 7], ['min + abs', 5],
  ];
  for (const [source, expected] of cases) {
    assert.equal(evaluate(source, { _x: 3, x2: 4, min: 2, abs: 3 }), expected, source);
  }
});

test('floor division and modulo obey sign and integer identity', () => {
  for (let a = -25; a <= 25; a++) {
    for (let b = -7; b <= 7; b++) {
      if (!b) continue;
      const quotient = evaluate('a // b', { a, b });
      const remainder = evaluate('a % b', { a, b });
      assert.equal(quotient, Math.floor(a / b) || 0);
      assert.equal(quotient * b + remainder, a);
      assert.ok(remainder === 0 || Math.sign(remainder) === Math.sign(b));
      assert.ok(Math.abs(remainder) < Math.abs(b));
      if (quotient === 0) assert.equal(Object.is(quotient, -0), false);
      if (remainder === 0) assert.equal(Object.is(remainder, -0), false);
    }
  }
  assert.equal(evaluate('-5.5 // 2'), -3);
  assert.equal(evaluate('-5.5 % 2'), 0.5);
  assert.equal(evaluate('5.5 % -2'), -0.5);
  assert.equal(evaluate('z // 2', { z: -0 }), 0);
  assert.equal(evaluate('z % -2', { z: -0 }), 0);
});

test('getter order, shared operands, short circuit, and own properties', () => {
  const reads = [];
  const variables = Object.create({ inherited: 9 });
  for (const [name, value] of [['a', 1], ['b', 2], ['c', 3]]) {
    Object.defineProperty(variables, name, { get() { reads.push(name); return value; } });
  }
  assert.equal(evaluate('a < b <= c', variables), true);
  assert.deepEqual(reads.splice(0), ['a', 'b', 'c']);
  assert.equal(evaluate('c < b < a', variables), false);
  assert.deepEqual(reads.splice(0), ['c', 'b']);
  assert.equal(evaluate('a + b * c + a', variables), 8);
  assert.deepEqual(reads.splice(0), ['a', 'b', 'c', 'a']);
  assert.equal(evaluate('max(c, b, a)', variables), 3);
  assert.deepEqual(reads.splice(0), ['c', 'b', 'a']);
  assert.equal(evaluate('2 < 1 < missing'), false);
  assert.equal(evaluate('2 < 1 < (1 / 0)'), false);
  errorAt('  inherited', 3, variables);
  for (const source of ['a + nope(1)', 'a + abs(1, 2)', 'a + min()', 'a + max()', 'a + abs()']) {
    errorAt(source, 5, variables);
    assert.deepEqual(reads, []);
  }
  errorAt('2 < 1 < nope(1)', 9);
  errorAt('2 < 1 < abs(1, 2)', 9);
  errorAt('2 < 1 < (1 + )', 14);
});

test('errors retain token UTF-16 columns, including whitespace and EOF', () => {
  for (const op of ['/', '//', '%']) {
    errorAt(` \t1   ${op} -0`, 7);
  }
  for (const [source, column] of [
    ['   missing', 4], ['  @', 3], ['  😀', 3], ['1 +\n\t @', 7],
    ['', 1], [' \t\n', 4], ['1 +   ', 7], ['(1  ', 5],
    ['1   2', 5], ['1   foo', 5], ['1 = 2', 3], ['1 ! 2', 3],
    ['1e+', 2], ['.', 1], ['min(1,)', 7], ['abs(1 2)', 7],
    ['  nope(1)', 3], ['  abs()', 3], ['min(1)  (2)', 9],
  ]) errorAt(source, column);
});

test('100,001-operand flat chains run without per-operand recursion', () => {
  const count = 100001;
  const cases = [
    [Array(count).fill('1').join(' + '), count],
    [Array(count).fill('1').join(' * '), 1],
    [Array.from({ length: count }, (_, i) => String(i)).join(' < '), true],
    ['max(' + Array.from({ length: count }, (_, i) => String(i)).join(',') + ')', count - 1],
  ];
  for (const [source, expected] of cases) {
    const start = performance.now();
    assert.equal(evaluate(source), expected);
    const elapsed = performance.now() - start;
    console.log(`Long formula (${source.length} UTF-16 units): ${elapsed.toFixed(1)} ms`);
    assert.ok(elapsed < 1000, `Evaluation took ${elapsed.toFixed(1)} ms`);
  }
});

